func isInsideWorkspace(root, path string) bool {
	rel, err := filepath.Rel(root, path)
	if err != nil {
		return false
	}
	return !strings.HasPrefix(rel, "..")
}

func TestCreateEntryCreatesFile(t *testing.T) {
	root := t.TempDir()
	handler := NewFileHandler(root, []string{".go"})

	recorder := postJSON(t, handler.CreateEntry, map[string]string{"path": "main.go", "type": "file"})
	if recorder.Code != http.StatusOK {
		t.Fatalf("status=%d body=%s", recorder.Code, recorder.Body.String())
	}
}

func truncateRunes(s string, limit int) string {
	runes := []rune(s)
	if len(runes) <= limit {
		return s
	}
	return string(runes[:limit])
}

type Notification struct {
	ID        string
	WorkspaceID string
	Message   string
	CreatedAt time.Time
}

func NewNotification(workspaceID, message string) Notification {
	return Notification{ID: NewID(), WorkspaceID: workspaceID, Message: message, CreatedAt: time.Now()}
}

func (d *DB) GetProject(id string) (*Project, error) {
	var p Project
	err := d.QueryRow(`SELECT id, name, path FROM projects WHERE id = ?`, id).Scan(&p.ID, &p.Name, &p.Path)
	if err != nil {
		return nil, err
	}
	return &p, nil
}

